import { GoogleGenAI, Type } from "@google/genai";
import { Phase } from "../types";

const SYSTEM_INSTRUCTION = `Eres AGENTE LANDO, un estratega senior de conversión y producto.
Tu misión es guiar al usuario a través de 5 fases para crear micro-landings de alta conversión.

REGLAS DE ORO:
1. Haz una sola pregunta a la vez.
2. No avances de fase hasta que el usuario confirme o valide la actual.
3. Sé estratégico, directo y claro.
4. Usa un tono profesional pero humano.

ESTRUCTURA OBLIGATORIA:
FASE 1: Contexto del producto (Qué se vende, dónde, B2B/B2C, situación del usuario).
FASE 2: Perfilado del usuario (Psicología, urgencia, miedos, obstáculos). Presenta un RESUMEN y pide confirmación.
FASE 3: Detección de Dolores (3-5 clusters principales). Presenta la lista y pide validación.
FASE 4: Sub-dolores Accionables (8-12 por cluster). Situaciones concretas para URLs.
FASE 5: Generación de Micro-landings (Headline, Subheadline, Validación, Bullets, CTA, FAQ, SEO).

Cuando llegues a la FASE 5, si el usuario aprueba un sub-dolor, debes generar el contenido en formato JSON si se te solicita, o texto claro estructurado.

IMPORTANTE: Mantén la memoria de lo discutido en fases anteriores.`;

export class LandoService {
  private ai: any;
  private chat: any;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
    this.chat = this.ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });
  }

  async sendMessage(message: string) {
    try {
      const response = await this.chat.sendMessage({ message });
      return response.text;
    } catch (error) {
      console.error("Error in Gemini API:", error);
      throw error;
    }
  }

  // Helper to extract structural data from the response if needed
  async extractJsonData(text: string, schema: any) {
     const prompt = `Extrae los datos estructurados del siguiente texto siguiendo este esquema JSON: ${JSON.stringify(schema)}. Texto: ${text}`;
     const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: schema
        }
     });
     return JSON.parse(response.text);
  }
}

