import Vault from './components/Vault';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    currentPhase: Phase.CONTEXT,
    history: [],
    generatedLandings: []
  });
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [lando, setLando] = useState<LandoService | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize Lando Agent
  useEffect(() => {
    // Note: process.env.API_KEY is pre-configured
    const service = new LandoService(process.env.API_KEY || '');
    setLando(service);

    const startConversation = async () => {
      setIsLoading(true);
      const initialMessage = "Hola, soy LANDO. Mi trabajo es ayudarte a crear micro-landingpages de alta conversión. Antes de escribir nada, necesito entender muy bien tu producto y a tus usuarios. Cuéntame, ¿qué producto o servicio ofreces y en qué mercado te mueves?";
      setState(prev => ({
        ...prev,
        history: [{ role: 'model', text: initialMessage }]
      }));
      setIsLoading(false);
    };

    startConversation();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [state.history, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading || !lando) return;

    const userMessage = input.trim();
    setInput('');
    setIsLoading(true);

    // Update history with user message
    setState(prev => ({
      ...prev,
      history: [...prev.history, { role: 'user', text: userMessage }]
    }));

    try {
      const response = await lando.sendMessage(userMessage);

      // Heuristic Phase detection logic (simple version for this demo)
      // In a real app, we might use the JSON extraction helper to check state
      let newPhase = state.currentPhase;
      const lowerResp = response.toLowerCase();

      if (lowerResp.includes('fase 2') || lowerResp.includes('perfilado')) {
         newPhase = Phase.PROFILING;
      }
      if (lowerResp.includes('fase 3') || lowerResp.includes('clusters')) {
         newPhase = Phase.CLUSTERS;
      }
      if (lowerResp.includes('fase 4') || lowerResp.includes('sub-dolores')) {
         newPhase = Phase.SUBPAINS;
      }
      if (lowerResp.includes('fase 5') || lowerResp.includes('micro-landing')) {
         newPhase = Phase.LANDINGS;
      }

      setState(prev => ({
        ...prev,
        currentPhase: newPhase,
        history: [...prev.history, { role: 'model', text: response }]
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        history: [...prev.history, { role: 'model', text: "Lo siento, tuve un error en mi procesamiento estratégico. ¿Podrías repetir lo último?" }]
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden">
      {/* Header / Nav */}
      <header className="bg-slate-900 text-white py-3 px-6 flex items-center justify-between shadow-lg z-20">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-500 p-1.5 rounded-lg shadow-inner">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold tracking-tight">AGENTE LANDO</h1>
            <p className="text-[10px] text-indigo-300 font-medium uppercase tracking-widest">Estratega de Conversión</p>
          </div>
        </div>
        <div className="flex gap-4 text-xs font-semibold text-slate-400">
          <span className="hidden sm:inline">Misión: Conversión Máxima</span>
          <span className="text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded border border-indigo-400/20">Versión 1.0</span>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Sidebar / Vault */}
        <aside className="hidden lg:block w-80 flex-shrink-0">
          <Vault state={state} />
        </aside>

        {/* Chat Main Area */}
        <main className="flex-1 flex flex-col min-w-0 bg-white shadow-sm relative">
          <PhaseStepper currentPhase={state.currentPhase} />

          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 md:p-8 space-y-4 bg-slate-50/50"
          >
            {state.history.map((msg, i) => (
              <ChatMessage key={i} message={msg} />
            ))}
            {isLoading && (
              <div className="flex justify-start mb-6">
                <div className="bg-white border border-slate-200 rounded-2xl rounded-tl-none p-4 shadow-sm">
                  <div className="flex gap-1.5">
                    <div className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                    <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 bg-white border-t border-slate-200">
            <div className="max-w-4xl mx-auto flex gap-3 items-end">
              <div className="flex-1 relative group">
                <textarea
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Escribe aquí tu respuesta estratégica..."
                  rows={1}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-4 pr-12 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all resize-none min-h-[50px] max-h-32 text-slate-800 text-sm md:text-base"
