                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Escribe tu respuesta para LANDO..."
                    rows={1}
                    className="flex-1 bg-transparent border-none focus:ring-0 py-2 px-3 resize-none max-h-40 text-sm text-slate-700"
