import React, { useState, useEffect, useRef } from 'react';
import { Phase, Message, AppState } from './types';
import { LandoService } from './services/gemini';
import PhaseStepper from './components/PhaseStepper';
import ChatMessage from './components/ChatMessage';
import Vault from './components/Vault';
import Sidebar from './components/Sidebar';
import LandingPage from './components/LandingPage';

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'app'>('landing');
  const [state, setState] = useState<AppState>({
    currentPhase: Phase.ONBOARDING,
    history: [],
    vault: {
      proyecto: {},
      perfil: {},
      clusters: [],
      subDolores: [],
      landings: []
    }
  });
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [lando, setLando] = useState<LandoService | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const service = new LandoService(process.env.API_KEY || '');
    setLando(service);

    const startConversation = async () => {
      setIsLoading(true);
      const welcome = "Hola, soy LANDO.\n\nMi trabajo es ayudarte a crear micro-landingpages de alta conversión entendiendo primero a tus usuarios y sus dolores reales. Antes de escribir una sola landing, necesito entender tu contexto.\n\nPara empezar simple: **¿Qué vendes exactamente?** (producto, servicio, asesoría, app, curso, etc.)";
      setState(prev => ({
        ...prev,
        history: [{ role: 'model', text: welcome }]
      }));
      setIsLoading(false);
    };

    if (view === 'app') {
      startConversation();
    }
  }, [view]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [state.history, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading || !lando) return;

    const userMessage = input.trim();
    setInput('');
    setIsLoading(true);

    const newHistory = [...state.history, { role: 'user', text: userMessage } as Message];
    setState(prev => ({ ...prev, history: newHistory }));

    try {
      const response = await lando.sendMessage(userMessage);

      const chatContext = [...newHistory, { role: 'model', text: response } as Message].map(m => `${m.role}: ${m.text}`).join('\n');
      const updatedVault = await lando.syncVault(chatContext);

      let nextPhase = state.currentPhase;
      const lowerResp = response.toLowerCase();

      if (lowerResp.includes('perfil') || lowerResp.includes('fase 2')) nextPhase = Phase.USER_PROFILE;
      if (lowerResp.includes('cluster') || lowerResp.includes('fase 3')) nextPhase = Phase.CLUSTERS;
      if (lowerResp.includes('sub-dolor') || lowerResp.includes('fase 4')) nextPhase = Phase.SUBPAINS;
      if (lowerResp.includes('micro-landing') || lowerResp.includes('fase 5')) nextPhase = Phase.LANDINGS;

      setState(prev => ({
        ...prev,
        currentPhase: nextPhase,
        history: [...newHistory, { role: 'model', text: response }],
        vault: updatedVault || prev.vault
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        history: [...newHistory, { role: 'model', text: "Perdón, tuve un desliz en mi análisis estratégico. ¿Podemos retomar?" }]
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (view === 'landing') {
    return <LandingPage onStart={() => setView('app')} />;
  }

  return (
    <div className="flex h-screen bg-white overflow-hidden text-slate-900 selection:bg-indigo-100 selection:text-indigo-900">
      <aside className="hidden md:flex flex-shrink-0">
        <Sidebar />
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <PhaseStepper currentPhase={Math.max(1, state.currentPhase + 1)} />

        <div className="flex flex-1 overflow-hidden">
          <main className="flex-1 flex flex-col bg-white border-r border-slate-200">
            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-6 md:p-12 space-y-8 bg-slate-50/20"
            >
              <div className="max-w-3xl mx-auto w-full">
                {state.history.map((msg, i) => (
                  <ChatMessage key={i} message={msg} />
                ))}
                {isLoading && (
                  <div className="flex justify-start mb-6">
                    <div className="bg-white border border-slate-200 rounded-3xl rounded-tl-none p-5 shadow-sm">
                      <div className="flex gap-2">
                        <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
                        <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                        <div className="w-2 h-2 bg-indigo-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="p-8 bg-white border-t border-slate-200/60">
              <div className="max-w-3xl mx-auto">
                <div className="group relative flex items-end gap-3 bg-slate-50 border border-slate-200 rounded-[2rem] p-3 focus-within:bg-white focus-within:ring-4 focus-within:ring-indigo-500/10 focus-within:border-indigo-500 transition-all shadow-sm">
                  <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Escribe tu respuesta estratégica..."
                    rows={1}
                    className="flex-1 bg-transparent border-none focus:ring-0 py-3 px-5 resize-none max-h-48 text-base text-slate-700 font-medium placeholder:text-slate-400"
                  />
                  <button 
                    onClick={handleSend}
                    disabled={isLoading || !input.trim()}
                    className="p-4 bg-indigo-600 text-white rounded-[1.5rem] hover:bg-indigo-700 disabled:opacity-40 transition-all shadow-xl shadow-indigo-600/20 active:scale-95"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                  </button>
                </div>
                <div className="flex justify-between items-center mt-4 px-4">
                  <div className="flex items-center gap-2">
                    <span className="flex h-2 w-2 relative">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-2 w-2 bg-indigo-500"></span>
                    </span>
                    <span className="text-[11px] text-slate-400 font-black uppercase tracking-widest">LANDO v1.0 Activo</span>
                  </div>
                  <p className="text-[11px] text-slate-400 font-medium italic">Presiona Enter para enviar la estrategia</p>
                </div>
              </div>
            </div>
          </main>

          <aside className="hidden lg:block w-96 flex-shrink-0">
            <Vault state={state} />
          </aside>
        </div>
      </div>
    </div>
  );
};

export default App;
